// Construye el prompt de agente con el estado del gemelo digital
const gemelo = $input.first().json;

// contexto compacto: estado + ultimos 10 registros del historial
const contexto = {
  ultimo_update: gemelo.ultimo_update,
  estado_actual: gemelo.estado_actual,
  historial_reciente: (gemelo.historial_1h || []).slice(-10),
  alertas_activas: gemelo.alertas_activas,
  prediccion_30min: gemelo.prediccion_30min,
  umbrales: gemelo.umbrales,
  resumen_anterior: gemelo.resumen_llm
};

const prompt = `Eres un agente de control de un hogar inteligente.
Tienes disponibles las siguientes herramientas:
- activar_actuador(dispositivo, estado)   // dispositivo: "led", estado: true|false
- enviar_notificacion(mensaje)
- registrar_evento(descripcion)
- ajustar_umbral(sensor, nuevo_umbral)    // sensor: "temperatura" o "audio"

Estado del gemelo digital (JSON): ${JSON.stringify(contexto)}

Reglas:
- El LED es la alarma visual del hogar: enciendelo si hay una condicion anormal (temperatura sobre su umbral, audio sobre su umbral, alerta activa o prediccion que supere el umbral) y apagalo si todo esta normal.
- Usa enviar_notificacion solo para condiciones anormales.
- Usa registrar_evento para dejar constancia de lo observado en cada ciclo.
- Responde en espanol.

Decide que acciones ejecutar. Responde SOLO en JSON valido con exactamente esta estructura:
{
  "acciones": [
    { "herramienta": "activar_actuador", "parametros": { "dispositivo": "led", "estado": true } }
  ],
  "razonamiento": "explicacion breve de la decision"
}`;

return [{ json: { model: 'phi3:mini', prompt, stream: false, format: 'json' } }];

// Parsea la respuesta del LLM y genera un item por accion.
// Tolerante con las variaciones tipicas de un modelo pequeno (phi3:mini).
const HERRAMIENTAS = ['activar_actuador', 'enviar_notificacion', 'registrar_evento', 'ajustar_umbral'];
const r = $input.first().json;
let d;
try {
  d = JSON.parse(r.response);
} catch (e) {
  // JSON invalido: no se ejecuta nada, se registra el problema
  return [{ json: { herramienta: 'registrar_evento', parametros: { descripcion: 'LLM devolvio JSON invalido' }, _error: true } }];
}
const crudas = Array.isArray(d.acciones) ? d.acciones : (Array.isArray(d.actions) ? d.actions : []);
const normalizadas = [];
for (const a of crudas) {
  if (!a || typeof a !== 'object') continue;
  let herramienta = a.herramienta || a.tool || a.accion || a.nombre;
  let parametros = a.parametros || a.params || a.parameters;
  if (!herramienta) {
    // formato alternativo: { "activar_actuador": { ... } }
    const claves = Object.keys(a).filter(k => HERRAMIENTAS.includes(k));
    if (claves.length === 1) {
      herramienta = claves[0];
      parametros = a[claves[0]];
    }
  }
  if (!HERRAMIENTAS.includes(herramienta)) continue;
  normalizadas.push({ json: { herramienta, parametros: (parametros && typeof parametros === 'object') ? parametros : {} } });
}
return normalizadas;

// Prepara el registro del ciclo de razonamiento completo
const r = $input.first().json;
let d;
try {
  d = JSON.parse(r.response);
} catch (e) {
  d = { acciones: [], razonamiento: 'JSON invalido: ' + String(r.response).slice(0, 200) };
}
const razonamiento = d.razonamiento || d.reasoning || d.explicacion || d.razon || '(el modelo no entrego razonamiento)';
const acciones = Array.isArray(d.acciones) ? d.acciones : (Array.isArray(d.actions) ? d.actions : []);
return [{ json: { razonamiento: String(razonamiento), acciones } }];
